/// <summary>
/// PricingAttribute of table <c>WHSInventFixedLocation</c> field InventSiteId.
/// </summary>
[UPSPricingMetadataDiscovery][UPSPricingAttributeSourceDiscovery(UPSPricingAttributeSource::Product, UPSPricingAttributeSourceLevel::Line)]
internal class UPSPricingAttributeWHSInventFixedLocationInventSiteId extends UPSPricingAttributeWHSInventFixedLocation implements UPSIPricingAttribute
{
}

Method.Source:
public str getName()
{
    return fieldPName(WHSInventFixedLocation, InventSiteId);
}

public Set getAllowedValues()
{
    var                    ret = new Set(Types::String);
    WHSInventFixedLocation wHSInventFixedLocation;

    while select wHSInventFixedLocation
        group by InventSiteId
    {
        if (! ret.in(wHSInventFixedLocation.InventSiteId))
        {
            ret.add(wHSInventFixedLocation.InventSiteId);
        }
    }

    return ret;
}

protected void setQueryBuildDatasourceRange(QueryBuildDataSource _qbds, anytype _value)
{
    QueryBuildRange qbr;

    qbr = _qbds.addRange(fieldNum(WHSInventFixedLocation, InventSiteId));
    qbr.value(queryValue(_value));
}
